function escapeRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function replacePhrase(text, en, vi) {
  return text.replace(new RegExp(`\\b${escapeRegex(en)}\\b`, 'gi'), vi);
}

function clean(text) {
  return text
    .replace(/n\.e\.c\./gi, 'chưa được phân vào đâu')
    .replace(/\s*;\s*/g, '; ')
    .replace(/\s*,\s*/g, ', ')
    .replace(/\s+/g, ' ')
    .replace(/\s+([,;:)])/g, '$1')
    .replace(/([(])\s+/g, '$1')
    .trim();
}

function translateNounPhrase(value) {
  let text = clean(value);
  for (const [en, vi] of PHRASES) text = replacePhrase(text, en, vi);
  for (const [en, vi] of GENERIC) text = replacePhrase(text, en, vi);
  return clean(text);
}

