function sentenceCaseVi(text) {
  if (!text) return text;
  return text.charAt(0).toUpperCase() + text.slice(1);
}

function translateIndustryTitle(title) {
  const source = clean(String(title || ''));
  if (!source) return '';
  const exact = EXACT.get(source);
  if (exact) return exact;
  for (const [pattern, render] of PREFIX_RULES) {
    const match = source.match(pattern);
    if (match) return sentenceCaseVi(clean(render(match[1])));
  }
  return sentenceCaseVi(translateNounPhrase(source));
}

module.exports = {
  translateIndustryTitle,
  translateNounPhrase,
};
